solutions.naive:
class Solution:
    def hIndex(self, citations: list[int]) -> int:
        n = len(citations)
        ans = 0
        for h in range(n + 1):
            count = 0
            for c in citations:
                if c >= h:
                    count += 1
            if count >= h:
                ans = h
        return ans

